use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (xgrid: Vec<Vec<f32>>, ygrid: Vec<Vec<f32>>)
    ensures
        // Shapes
        xgrid.len() == y.len(),
        ygrid.len() == y.len(),
        forall|i: int| 0 <= i < y.len() ==> xgrid[i].len() == x.len(),
        forall|i: int| 0 <= i < y.len() ==> ygrid[i].len() == x.len(),

        // Content: each row of xgrid equals x
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==> xgrid[i][j] == x[j],

        // Content: each row of ygrid is filled with y[i]
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==> ygrid[i][j] == y[i],
{
    let rows = y.len();
    let cols = x.len();

    let mut xgrid: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut ygrid: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for &yv in &y
        invariant
            xgrid.len() == ygrid.len(),
            xgrid.len() <= y.len(),

            // Established rows so far have correct shapes
            forall|i: int| 0 <= i < xgrid.len() ==> xgrid[i].len() == x.len(),
            forall|i: int| 0 <= i < ygrid.len() ==> ygrid[i].len() == x.len(),

            // Established rows so far have correct contents
            forall|i: int, j: int|
                0 <= i < xgrid.len() && 0 <= j < x.len() ==> xgrid[i][j] == x[j],
            forall|i: int, j: int|
                0 <= i < ygrid.len() && 0 <= j < x.len() ==> ygrid[i][j] == y[i],
        decreases y.len() - xgrid.len(),
    {
        // Each row of xgrid is a copy of x
        xgrid.push(x.clone());

        // Each row of ygrid is filled with the corresponding y value
        ygrid.push(vec![yv; cols]);

        // Help the prover connect the pushed y-value with y[index]
        assert(ygrid.len() == xgrid.len());
    }

    (xgrid, ygrid)
}

} // verus!

